    "content": "import React, { useState, useEffect } from 'react';
import {
  IonPage,
  IonContent,
  IonList,
  IonItem,
  IonLabel,
  IonText,
  IonToggle,
  IonIcon,
  IonButton,
  IonAlert,
  IonLoading,
  IonToast,
  IonFab,
  IonFabButton,
  IonModal,
  IonHeader,
  IonToolbar,
  IonTitle,
  IonButtons,
  IonInput,
  IonSelect,
  IonSelectOption,
  IonNote,
  IonSearchbar,
  useIonViewWillEnter,
  IonInfiniteScroll,
  IonInfiniteScrollContent
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, cashOutline, informationCircleOutline, checkmarkCircle } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import {
  PosRewardCatalogItem,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
} from '../api/PosRewardCatalogItemApi';
import './PosRewardCatalogItemPage.css';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormState {
  name: string;
  rewardType: string;
  requiredPoints: number;
  discountValue: number | undefined;
  freeProductId: number | undefined;
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [posRewardCatalogItems, setPosRewardCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [filteredItems, setFilteredItems] = useState<PosRewardCatalogItem[]>([]);
  const [searchText, setSearchText] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string>('');
  const [showDeleteAlert, setShowDeleteAlert] = useState<boolean>(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);
  const [showModal, setShowModal] = useState<boolean>(false);
  const [isEditing, setIsEditing] = useState<boolean>(false);
  const [selectedItem, setSelectedItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: 'DISCOUNT',
    requiredPoints: 0,
    discountValue: undefined,
    freeProductId: undefined,
    isActive: true,
    description: '',
  });

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event; 
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const [formErrors, setFormErrors] = useState({
    name: '',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
  });

  const validateForm = () => {
    let isValid = true;
    const newErrors = { name: '', requiredPoints: '', discountValue: '', freeProductId: '' };

    if (!formState.name.trim()) {
      newErrors.name = 'El nombre es requerido.';
      isValid = false;
    }
    if (formState.requiredPoints <= 0) {
      newErrors.requiredPoints = 'Los puntos requeridos deben ser mayores a 0.';
      isValid = false;
    }
    if (formState.rewardType === 'DISCOUNT' && (!formState.discountValue || formState.discountValue <= 0)) {
      newErrors.discountValue = 'El valor de descuento es requerido y debe ser mayor a 0.';
      isValid = false;
    }
    if (formState.rewardType === 'PRODUCT' && (!formState.freeProductId || formState.freeProductId <= 0)) {
      newErrors.freeProductId = 'El ID del producto es requerido y debe ser mayor a 0.';
      isValid = false;
    }

    setFormErrors(newErrors);
    return isValid;
  };

  const fetchPosRewardCatalogItems = async () => {
    setLoading(true);
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setPosRewardCatalogItems(data);
      setFilteredItems(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar los items del catálogo.');
    }
    setLoading(false);
  };

  useIonViewWillEnter(() => {
    fetchPosRewardCatalogItems();
  });

  useEffect(() => {
    if (searchText === '') {
      setFilteredItems(posRewardCatalogItems);
    } else {
      setFilteredItems(
        posRewardCatalogItems.filter(
          (item) =>
            item.name.toLowerCase().includes(searchText.toLowerCase()) ||
            item.rewardType.toLowerCase().includes(searchText.toLowerCase()) ||
            item.description?.toLowerCase().includes(searchText.toLowerCase())
        )
      );
    }
  }, [searchText, posRewardCatalogItems]);

  const handleCreateClick = () => {
    setIsEditing(false);
    setFormState({
      name: '',
      rewardType: 'DISCOUNT',
      requiredPoints: 0,
      discountValue: undefined,
      freeProductId: undefined,
      isActive: true,
      description: '',
    });
    setFormErrors({ name: '', requiredPoints: '', discountValue: '', freeProductId: '' });
    setShowModal(true);
  };

  const handleEditClick = (item: PosRewardCatalogItem) => {
    setIsEditing(true);
    setSelectedItem(item);
    setFormState({
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints,
      discountValue: item.discountValue,
      freeProductId: item.freeProductId,
      isActive: item.isActive,
      description: item.description || '',
    });
    setFormErrors({ name: '', requiredPoints: '', discountValue: '', freeProductId: '' });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!validateForm()) return;

    setLoading(true);
    try {
      const payload = {
        companyId,
        name: formState.name,
        rewardType: formState.rewardType,
        requiredPoints: formState.requiredPoints,
        discountValue: formState.rewardType === 'DISCOUNT' ? formState.discountValue : undefined,
        freeProductId: formState.rewardType === 'PRODUCT' ? formState.freeProductId : undefined,
        isActive: formState.isActive,
        description: formState.description,
      };

      if (isEditing && selectedItem) {
        await updatePosRewardCatalogItem(selectedItem.posRewardCatalogItemId, payload);
        setError('Item del catálogo actualizado con éxito.');
      } else {
        await createPosRewardCatalogItem(payload);
        setError('Item del catálogo creado con éxito.');
      }
      setShowModal(false);
      fetchPosRewardCatalogItems();
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el item del catálogo.');
    }
    setLoading(false);
  };

  const handleDeleteClick = (item: PosRewardCatalogItem) => {
    setItemToDelete(item);
    setShowDeleteAlert(true);
  };

  const confirmDelete = async () => {
    if (itemToDelete) {
      setLoading(true);
      try {
        await deletePosRewardCatalogItem(itemToDelete.posRewardCatalogItemId, companyId);
        setError('Item del catálogo eliminado con éxito.');
        fetchPosRewardCatalogItems();
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar el item del catálogo.');
      }
      setLoading(false);
    }
  };

  // Infinite scroll - not strictly needed given no backend pagination for CRUD_ONLY, but mandated
  const loadMoreItems = () => {
    // In a real scenario, this would fetch more items from the backend
    // For this CRUD_ONLY implementation, we just complete the infinite scroll
    // to avoid it staying active if the list is already fully loaded.
    // If there were actual pagination, we'd update `posRewardCatalogItems` here.
  };

  return (
    <IonPage className="posrewardcatalogitem-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Catálogo de Recompensas — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message={'Cargando items...'} />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.toLowerCase().includes('error') ? 'danger' : 'success'}
        />

        <IonSearchbar
          value={searchText}
          onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchText(e.detail.value!)}
          placeholder="Buscar recompensa..."
          debounce={300}
        ></IonSearchbar>

        <IonList>
          {filteredItems.map((item) => (
            <IonItem key={item.posRewardCatalogItemId} lines="full" detail>
              <IonIcon icon={cashOutline} slot="start" className="list-item-icon" />
              <IonLabel>
                <IonText className="item-name">{item.name}</IonText>
                <IonNote className="item-description">{item.description || 'Sin descripción'}</IonNote>
                <IonNote className="item-points">Puntos requeridos: {item.requiredPoints.toFixed(2)}</IonNote>
                <IonNote className="item-type">Tipo: {item.rewardType}</IonNote>
                {item.rewardType === 'DISCOUNT' && (
                  <IonNote className="item-value">Valor de descuento: ${item.discountValue?.toFixed(2) ?? '0.00'}</IonNote>
                )}
                {item.rewardType === 'PRODUCT' && (
                  <IonNote className="item-value">ID Producto gratis: {item.freeProductId ?? 'N/A'}</IonNote>
                )}
                <IonNote className="item-date">Creado: {toHermosillo(item.created_At)}</IonNote>
                {item.updated_at && <IonNote className="item-date">Actualizado: {toHermosillo(item.updated_at)}</IonNote>}
              </IonLabel>
              <div className="item-actions">
                <IonToggle
                  checked={item.isActive}
                  onIonChange={async (e: CustomEvent<ToggleChangeEventDetail>) => {
                    setLoading(true);
                    try {
                      await updatePosRewardCatalogItem(item.posRewardCatalogItemId, { isActive: e.detail.checked });
                      setError('Estado de actividad actualizado.');
                      fetchPosRewardCatalogItems();
                    } catch (err) {
                      setError((err as Error).message ?? 'Error al actualizar el estado.');
                    }
                    setLoading(false);
                  }}
                  color="primary"
                  slot="end"
                >
                  <IonLabel>{item.isActive ? 'Activo' : 'Inactivo'}</IonLabel>
                </IonToggle>
                <IonButton fill="clear" color="primary" onClick={() => handleEditClick(item)}>
                  <IonIcon icon={createOutline} slot="icon-only" />
                </IonButton>
                <IonButton fill="clear" color="danger" onClick={() => handleDeleteClick(item)}>
                  <IonIcon icon={trashOutline} slot="icon-only" />
                </IonButton>
              </div>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={(ev: CustomEvent<void>) => {
          loadMoreItems();
          (ev.target as HTMLIonInfiniteScrollElement).complete();
        }}>
          <IonInfiniteScrollContent loadingText="Cargando más recompensas..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleCreateClick}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar eliminación'}
          message={`¿Estás seguro de que quieres eliminar "${itemToDelete?.name}"?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete },
          ]}
        />

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="posrewardcatalogitem-modal">
