                className={formErrors.name ? 'ion-invalid ion-touched' : ''}
                errorText={formErrors.name}
              />

              <IonSelect
                fill="outline"
                label="Tipo de Recompensa *"
                labelPlacement="floating"
                value={formState.rewardType}
